// ============================================
// FORMAT OPENAI RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Handle error response
if (input.error) {
  return {
    success: false,
    error: {
      code: 'LLM_ERROR',
      message: input.error.message || 'OpenAI API error',
      http_status: 500
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'openai',
      model: prevData.model,
      tokens: { input: 0, output: 0 },
      latency_ms: Date.now() - startTime,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  };
}

const text = input.choices?.[0]?.message?.content || '';
const finishReason = input.choices?.[0]?.finish_reason || 'stop';
const modelUsed = input.model || prevData.model;

const _trace = {
  llm_response: text,
  service_response: input,
  provider: 'openai',
  model: modelUsed,
  tokens: {
    input: input.usage?.prompt_tokens || 0,
    output: input.usage?.completion_tokens || 0
  },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return {
  success: true,
  data: {
    text: text,
    model: modelUsed,
    finish_reason: finishReason
  },
  meta: {
    provider: 'openai',
    model: modelUsed,
    usage: {
      prompt_tokens: input.usage?.prompt_tokens || 0,
      completion_tokens: input.usage?.completion_tokens || 0,
      total_tokens: input.usage?.total_tokens || 0
    }
  },
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  _trace: _trace
};

